def decompose(cells):
    # greedy max rectangle covering all cells
    res=[]; rem=list(cells)
    while rem:
        rs={p[0] for p in rem}; cs={p[1] for p in rem}
        best=None
        for r in rs:
            for c in cs:
                n=sum(1 for i in range(min(rs),max(rs)+1) for j in range(min(cs),max(cs)+1) if (i,j) in set(rem))
                if best is None or n>best[0]: best=(n,r,c)
        n,r,c=best
        h=max(rs)-r+1; w=max(cs)-c+1
        if h*1==0 or w==0: break
        rects=[(r,i,c,j) for i in range(r,max(rs)+1) for j in range(c,max(cs)+1) if (i,j) in set(rem)]
        # take maximal rectangle anchored at (r,c) containing most cells
        cand=0
        for hh in range(1,max(rs)-r+2):
            for ww in range(1,max(cs)-c+2):
                if all((r+i,c+j) in set(rem) for i in range(hh) for j in range(ww)):
                    cand=max(cand,hh*ww)
        hh=ww=1
        while r+hh<=max(rs) and all((r+hh,c+j) in set(rem) for j in range(ww)): hh+=1
        hh-=1
        while c+ww<=max(cs) and all((r+i,c+ww) in set(rem) for i in range(hh)): ww+=1
        ww-=1
        res.append((r,c,hh,ww)); rem=[(i,j) for i,j in rem if not(r<=i<r+hh and c<=j<c+ww)]
    return res
