def f(g):
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    cells={}
    for i,r in enumerate(g):
        for j,x in enumerate(r):
            if x!=bg: cells.setdefault(x,set()).add((i,j))
    out=[[bg]*len(g[0]) for _ in g]
